                hap_bam=stage1_hap_bam,
                hap_bed=stage1_hap_bed,
                hap_vcf=stage1_hap_vcf,
            )
        )

        stage1_bam = self.tmp_dir.joinpath("hybrid_stage1.bam")
        stage1_job = Job(
            cmds.hybrid_stage1(
                out_aln=stage1_bam,
