            str(stage1_ins_bed),
            str(stage1_hap_vcf),
        ]
        rm_job2 = Job(Pipeline(Command(*rm_cmd, fail_ok=True)), "rm-tmp2", 0)

        stage2_bed = self.tmp_dir.joinpath("hybrid_stage2.bed")
