        transfer_jobs: Optional[List[Job]] = None
        transfer_concat_job: Optional[Job] = None
        input_to_apply = anno_target

        if self.pop_vcf:
            transfer_target = self.tmp_dir.joinpath(
                "combined_tmp_transfer.vcf.gz"
            )
            if self.skip_model_apply:
                transfer_target = self.output_vcf

            transfer_jobs, transfer_concat_job = build_transfer_jobs(
                transfer_target,
                self.pop_vcf,
                anno_target,
                self.tmp_dir,
                self.shards,
                self.pop_vcf_contigs,
                self.fai_data,
                self.dry_run,
                self.cores,
            )
            input_to_apply = transfer_target

        if self.skip_model_apply:
            return (
                call_job,
                select_job,
                mapq0_job,
                mapq0_slop_job,
                cat_merge_job,
                rm_job1,
                stage1_job,
                rm_job2,
                second_stage_job,
                rm_job3,
                third_stage_job,
                rm_job4,
                call2_job,
                subset_job,
                concat_job,
                rm_job5,
                anno_job,
                transfer_jobs,
                transfer_concat_job,
                None,
                None,
            )

        # Model Apply
        apply_vcf = self.tmp_dir.joinpath("combined_apply.vcf.gz")
        driver = Driver(
            reference=self.reference,
            thread_count=self.cores,
            interval=self.bed,
        )
        driver.add_algo(
            DNAModelApply(
                model=self.model_bundle.joinpath("hybrid.model"),
                vcf=input_to_apply,
                output=apply_vcf,
            )
        )
        apply_job = Job(
            Pipeline(Command(*driver.build_cmd())), "model-apply", self.cores
        )

        # Final normalize
        norm_job = Job(
            cmds.filter_norm(
                self.output_vcf,
                apply_vcf,
                self.reference,
                exclude_homref=not self.gvcf,
            ),
            "final-norm",
            0,
        )
        return (
            call_job,
            select_job,
            mapq0_job,
            mapq0_slop_job,
            cat_merge_job,
            rm_job1,
            stage1_job,
            rm_job2,
            second_stage_job,
            rm_job3,
            third_stage_job,
            rm_job4,
            call2_job,
            subset_job,
            concat_job,
            rm_job5,
            anno_job,
            transfer_jobs,
            transfer_concat_job,
            apply_job,
            norm_job,
        )
